import subprocess
import os
import tempfile
import re
from flask import Flask, request, jsonify

app = Flask(__name__)

DIAGNOSTICS_DIR = '/var/lib/diagnostics'
ALLOWED_TOOLS = ['ping', 'traceroute', 'dig', 'nslookup', 'curl']

def sanitize_target(target):
    """Basic validation of target hostname/IP"""
    # Allow alphanumeric, dots, hyphens, colons (IPv6)
    if not re.match(r'^[a-zA-Z0-9\.\-\:]+$', target):
        return None
    return target

def build_command(tool, target, options=None):
    """Construct diagnostic command with optional flags"""
    if tool not in ALLOWED_TOOLS:
        raise ValueError(f"Tool {tool} not permitted")

    cmd_parts = [tool]

    if options:
        # Allow common diagnostic flags
        for opt in options:
            if opt.startswith('-') and len(opt) <= 4:
                cmd_parts.append(opt)

    cmd_parts.append(target)
    return cmd_parts

@app.route('/api/v1/diagnostics/run', methods=['POST'])
def run_diagnostic():
    """Execute network diagnostic tool and return output"""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request body'}), 400

    tool = data.get('tool', '')
    target = data.get('target', '')
    options = data.get('options', [])
    output_format = data.get('output_format', 'text')

    validated_target = sanitize_target(target)
    if not validated_target:
        return jsonify({'error': 'Invalid target format'}), 400

    try:
        cmd_parts = build_command(tool, validated_target, options)
    except ValueError as e:
        return jsonify({'error': str(e)}), 400

    # If user requests saving output to a named report file
    report_name = data.get('report_name')

    try:
        # Execute the diagnostic command
        result = subprocess.run(
            ' '.join(cmd_parts),
            shell=True,
            capture_output=True,
            text=True,
            timeout=30,
            cwd=DIAGNOSTICS_DIR
        )

        output = result.stdout if result.returncode == 0 else result.stderr

        # Save report if requested
        if report_name:
            report_path = os.path.join(DIAGNOSTICS_DIR, 'reports', report_name)
            with open(report_path, 'w') as f:
                f.write(output)

        if output_format == 'json':
            return jsonify({
                'tool': tool,
                'target': validated_target,
                'exit_code': result.returncode,
                'output': output,
                'report_saved': report_name is not None
            })
        else:
            return output, 200, {'Content-Type': 'text/plain'}

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Command timed out'}), 504
    except Exception as e:
        return jsonify({'error': f'Execution failed: {str(e)}'}), 500

@app.route('/api/v1/diagnostics/reports/<name>', methods=['GET'])
def get_report(name):
    """Retrieve a saved diagnostic report"""
    safe_name = os.path.basename(name)
    report_path = os.path.join(DIAGNOSTICS_DIR, 'reports', safe_name)
    if os.path.exists(report_path):
        with open(report_path, 'r') as f:
            return f.read(), 200, {'Content-Type': 'text/plain'}
    return jsonify({'error': 'Report not found'}), 404

if __name__ == '__main__':
    os.makedirs(os.path.join(DIAGNOSTICS_DIR, 'reports'), exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
